@dataclass
class Stats:
    blanks: int = 0
    code: int = 0
    comments: int = 0
    blobs: Dict[str, "Stats"] = field(default_factory=dict)

    @property
    def lines(self) -> int:
        return self.blanks + self.code + self.comments

    def add_own(self, other: "Stats") -> None:
        self.blanks += other.blanks
        self.code += other.code
        self.comments += other.comments

    def copy_without_blobs(self) -> "Stats":
        return Stats(self.blanks, self.code, self.comments, {})

    def total_with_blobs(self) -> "Stats":
        total = Stats(self.blanks, self.code, self.comments, {})
        for child in self.blobs.values():
            ct = child.total_with_blobs()
            total.add_own(ct)
        return total


@dataclass
class Report:
    name: str
    stats: Stats


@dataclass
class LangAgg:
    name: str
    blanks: int = 0
    code: int = 0
    comments: int = 0
    reports: List[Report] = field(default_factory=list)
    children: Dict[str, List[Report]] = field(default_factory=lambda: defaultdict(list))

    @property
    def files(self) -> int:
        return len(self.reports)

    @property
    def own_stats(self) -> Stats:
        return Stats(self.blanks, self.code, self.comments, {})

    @property
    def own_lines(self) -> int:
        return self.blanks + self.code + self.comments

    def total_stats(self) -> Stats:
        total = Stats(self.blanks, self.code, self.comments, {})
        for reports in self.children.values():
            for rep in reports:
                total.add_own(rep.stats.total_with_blobs())
