# ---------------------------------------------------------------------------
# Language detection


def _parse_language_table() -> Dict[str, str]:
    mapping: Dict[str, str] = {}
    for line in LANGUAGES_TEXT.splitlines():
        if not line.startswith("┃ ") or "Language" in line and "Extensions" in line:
            continue
        if "━" in line:
            continue
        body = line.strip("┃").rstrip()
        body = body.strip()
        if not body:
            continue
        # The table has two columns separated by a run of spaces.  Language
        # names themselves may contain single spaces, so split on 2+ spaces.
        m = re.match(r"(.+?)\s{2,}(.+?)\s*$", body)
        if not m:
            continue
        lang, exts = m.group(1).strip(), m.group(2).strip()
        if exts == "<None>":
            continue
        for part in exts.split(","):
            ext = part.strip()
            if not ext or "..." in ext:
                continue
            # Do not try to use explanatory multi-word fragments as extensions.
            if " " in ext and ext not in {"🍇\u200b"}:
                continue
            mapping[ext.lower()] = lang
    return mapping


