def detect_shebang(text: str) -> Optional[str]:
    if not text.startswith("#!"):
        return None
    first = text.splitlines()[0].lower() if text.splitlines() else text.lower()
    if "python" in first:
        return "Python"
    if "bash" in first:
        return "BASH"
    if re.search(r"(?:/|env\s+)sh(?:\s|$)", first):
        return "Shell"
    if "zsh" in first:
        return "Zsh"
    if "fish" in first:
        return "Fish"
    if "ruby" in first:
        return "Ruby"
    if "perl" in first:
        return "Perl"
    if "node" in first or "deno" in first:
        return "JavaScript"
    if "php" in first:
        return "PHP"
    if "lua" in first:
        return "Lua"
    return None


def detect_language(display_path: str, abs_path: str, first_text: Optional[str] = None) -> Tuple[Optional[str], Optional[str]]:
    base = os.path.basename(display_path)
    lower_base = base.lower()
    if lower_base in SPECIAL_FILENAMES:
        return SPECIAL_FILENAMES[lower_base], None
    if lower_base.startswith("dockerfile"):
        return "Dockerfile", None
    ext = None
    if "." in base and not (base.startswith(".") and base.count(".") == 1):
        ext = base.rsplit(".", 1)[1]
        lang = EXT_MAP.get(ext.lower())
        if lang:
            return lang, None
    if first_text is not None:
        lang = detect_shebang(first_text)
        if lang:
            return lang, None
    return None, ext


def fence_language(info: str) -> Optional[str]:
    s = info.strip()
    if not s:
        return None
    # Markdown fences often use attributes like "{.rust}".
    if s.startswith("{") and s.endswith("}"):
        s = s[1:-1].strip()
    if s.startswith("."):
        s = s[1:]
    token = re.split(r"[\s,{}]+", s, 1)[0].strip().strip(".").lower()
    if not token:
        return None
    if token in FENCE_ALIASES:
        return FENCE_ALIASES[token]
    return EXT_MAP.get(token)


# ---------------------------------------------------------------------------
# Counting logic


def split_lines(text: str) -> List[str]:
    if text == "":
        return []
    return text.splitlines()


def read_file_text(path: str) -> str:
    try:
        with open(path, "rb") as f:
            data = f.read()
    except OSError:
        return ""
    # The observed program tolerates invalid UTF-8.  Replacement preserves line
    # structure while making the file countable.
    return data.decode("utf-8", errors="replace")


def count_plain_text(lines: List[str]) -> Stats:
    st = Stats()
    for line in lines:
        if line.strip():
            st.comments += 1
        else:
            st.blanks += 1
    return st


def count_no_comments(lines: List[str]) -> Stats:
    st = Stats()
    for line in lines:
        if line.strip():
            st.code += 1
        else:
            st.blanks += 1
    return st


def count_first_marker(lines: List[str], markers: Iterable[str]) -> Stats:
    markers = tuple(markers)
    st = Stats()
    for line in lines:
        stripped = line.lstrip()
        if not stripped:
            st.blanks += 1
        elif any(stripped.startswith(m) for m in markers):
            st.comments += 1
        else:
            st.code += 1
    return st


def _find_next_token(line: str, pos: int, starts: List[str], end: str) -> Tuple[int, Optional[str]]:
    """Return (index, token), choosing the earliest block start/end."""
    best_i = -1
    best_tok: Optional[str] = None
    for tok in starts + [end]:
        i = line.find(tok, pos)
        if i != -1 and (best_i == -1 or i < best_i or (i == best_i and len(tok) > len(best_tok or ""))):
            best_i, best_tok = i, tok
    return best_i, best_tok


def _advance_block(line: str, pos: int, depth: int, start: str, end: str, nested: bool) -> Tuple[int, int]:
    starts = [start] if nested else []
    while pos < len(line) and depth > 0:
        i, tok = _find_next_token(line, pos, starts, end)
        if i == -1:
            return len(line), depth
        if nested and tok == start:
            depth += 1
            pos = i + len(start)
        else:
            depth -= 1
            pos = i + len(end)
    return pos, depth


def _skip_string(line: str, i: int, quote_chars: str) -> int:
    quote = line[i]
    n = len(line)
    i += 1
    while i < n:
        c = line[i]
        if c == "\\":
            i += 2
            continue
        if c == quote:
            return i + 1
        i += 1
    return n


def count_generic(lines: List[str], line_comments: List[str], block_comments: List[Tuple[str, str, bool]], quote_chars: str = "\"'`") -> Stats:
    st = Stats()
    # Only a single active block type is needed for the languages handled here.
    active: Optional[Tuple[str, str, bool, int]] = None  # start, end, nested, depth
    # Prefer longer comment markers (e.g. Lua --[[ before --).
    line_comments = sorted(line_comments, key=len, reverse=True)
    block_comments = sorted(block_comments, key=lambda x: len(x[0]), reverse=True)

    for line in lines:
        if active is not None:
            start, end, nested, depth = active
            _, depth = _advance_block(line, 0, depth, start, end, nested)
            active = (start, end, nested, depth) if depth > 0 else None
            st.comments += 1
            continue

        if not line.strip():
            st.blanks += 1
            continue

        i = 0
        n = len(line)
        saw_code = False
        saw_comment = False
        while i < n:
            if line[i].isspace():
                i += 1
                continue

            if line[i] in quote_chars:
                saw_code = True
                i = _skip_string(line, i, quote_chars)
                continue

            matched_block: Optional[Tuple[str, str, bool]] = None
            for start, end, nested in block_comments:
                if line.startswith(start, i):
                    matched_block = (start, end, nested)
                    break
            if matched_block is not None:
                start, end, nested = matched_block
                saw_comment = True
                pos, depth = _advance_block(line, i + len(start), 1, start, end, nested)
                if depth > 0:
                    active = (start, end, nested, depth)
                    break
                i = pos
                continue

            if any(line.startswith(marker, i) for marker in line_comments):
                saw_comment = True
                break

            saw_code = True
            # Skip a run of ordinary characters for speed, stopping before any
            # possible special/comment/string character.
            specials = set(quote_chars)
            for marker in line_comments:
                specials.add(marker[0])
            for start, _, _ in block_comments:
                specials.add(start[0])
            i += 1
            while i < n and (not line[i].isspace()) and line[i] not in specials:
                i += 1

        if saw_code:
            st.code += 1
        elif saw_comment:
            st.comments += 1
        else:
            st.blanks += 1
    return st


def count_python(lines: List[str]) -> Stats:
    st = Stats()
    triple: Optional[str] = None
    for line in lines:
        if triple is not None:
            st.code += 1
            idx = line.find(triple)
            if idx != -1:
                # Toggle off at the first closing delimiter.  If another triple
                # starts later on the same line the whole line is still code;
                # exact string parsing is unnecessary for line counts.
                triple = None
            continue
        stripped = line.lstrip()
        if not stripped:
            st.blanks += 1
        elif stripped.startswith("#"):
            st.comments += 1
        else:
            st.code += 1
            # Detect a triple-quoted string opener if it is not closed later on
            # the same line.  Tokei treats all triple-string lines as code.
            for delim in ("'''", '"""'):
                idx = line.find(delim)
                if idx != -1 and line.find(delim, idx + 3) == -1:
                    triple = delim
                    break
    return st


def count_batch(lines: List[str]) -> Stats:
    st = Stats()
    for line in lines:
        s = line.strip()
        low = s.lower()
        if not s:
            st.blanks += 1
        elif low.startswith("rem ") or low == "rem" or s.startswith("::"):
            st.comments += 1
        else:
            st.code += 1
    return st


def count_markdown(lines: List[str]) -> Stats:
    st = Stats()
    in_fence = False
    fence_char = "`"
    fence_len = 3
    child_lang: Optional[str] = None
    child_lines: List[str] = []

    def add_child(lang: str, child: Stats) -> None:
        if lang in st.blobs:
            st.blobs[lang].add_own(child)
            for sub_lang, sub_stats in child.blobs.items():
                if sub_lang not in st.blobs[lang].blobs:
                    st.blobs[lang].blobs[sub_lang] = Stats()
                st.blobs[lang].blobs[sub_lang].add_own(sub_stats)
        else:
            st.blobs[lang] = child

    for line in lines:
        stripped = line.strip()
        if in_fence:
            if stripped.startswith(fence_char * fence_len):
                # Closing fence belongs to Markdown comments.
                if stripped:
                    st.comments += 1
                else:
                    st.blanks += 1
                if child_lang is not None:
                    add_child(child_lang, count_lines_for_language(child_lines, child_lang))
                in_fence = False
                child_lang = None
                child_lines = []
            else:
                child_lines.append(line)
            continue

        m = re.match(r"^\s*(`{3,}|~{3,})\s*([^`]*)$", line)
        if m:
            lang = fence_language(m.group(2))
            if lang is not None:
                st.comments += 1
                in_fence = True
                fence_char = m.group(1)[0]
                fence_len = len(m.group(1))
                child_lang = lang
                child_lines = []
                continue
        if stripped:
            st.comments += 1
        else:
            st.blanks += 1

    if in_fence and child_lang is not None:
        add_child(child_lang, count_lines_for_language(child_lines, child_lang))
    return st


def _count_html_parent_line(line: str, state: List[Optional[Tuple[str, str, bool, int]]]) -> str:
    # Use the generic block-comment state for HTML comments outside script/style.
    active = state[0]
    if active is not None:
        start, end, nested, depth = active
        _, depth = _advance_block(line, 0, depth, start, end, nested)
        state[0] = (start, end, nested, depth) if depth > 0 else None
        return "comment"
    if not line.strip():
        return "blank"
    i = line.find("<!--")
    if i != -1:
        before = line[:i].strip()
        if before:
            return "code"
        pos, depth = _advance_block(line, i + 4, 1, "<!--", "-->", False)
        if depth > 0:
            state[0] = ("<!--", "-->", False, depth)
        if depth == 0 and line[pos:].strip():
            return "code"
        return "comment"
    return "code"


def count_html(lines: List[str]) -> Stats:
    st = Stats()
    mode: Optional[str] = None
    child_lines: List[str] = []
    html_comment_state: List[Optional[Tuple[str, str, bool, int]]] = [None]

    def add_child(lang: str, child: Stats) -> None:
        if lang in st.blobs:
            st.blobs[lang].add_own(child)
        else:
            st.blobs[lang] = child

    for line in lines:
        lower = line.lower()
        if mode is not None:
            endtag = "</style" if mode == "CSS" else "</script"
            idx = lower.find(endtag)
            if idx != -1:
                before = line[:idx]
                if before:
                    child_lines.append(before)
                add_child(mode, count_lines_for_language(child_lines, mode))
                child_lines = []
                mode = None
                # The line containing the closing tag is parent HTML code.
                st.code += 1 if line.strip() else 0
                st.blanks += 0 if line.strip() else 1
            else:
                child_lines.append(line)
            continue

        style_idx = lower.find("<style")
        script_idx = lower.find("<script")
        candidates = [(style_idx, "CSS"), (script_idx, "JavaScript")]
        candidates = [(i, lang) for i, lang in candidates if i != -1]
        if candidates:
            idx, lang = min(candidates, key=lambda x: x[0])
            # Treat the opening-tag line as HTML code.  Content after the tag on
            # the same line is unusual; support the simple case.
            st.code += 1 if line.strip() else 0
            st.blanks += 0 if line.strip() else 1
            gt = line.find(">", idx)
            endtag = "</style" if lang == "CSS" else "</script"
            end_idx = lower.find(endtag, gt + 1 if gt != -1 else idx)
            if gt != -1 and end_idx != -1:
                content = line[gt + 1:end_idx]
                if content:
                    add_child(lang, count_lines_for_language([content], lang))
            else:
                mode = lang
                child_lines = []
                if gt != -1 and line[gt + 1:].strip():
                    child_lines.append(line[gt + 1:])
            continue

        cls = _count_html_parent_line(line, html_comment_state)
        if cls == "blank":
            st.blanks += 1
        elif cls == "comment":
            st.comments += 1
        else:
            st.code += 1

    if mode is not None:
        add_child(mode, count_lines_for_language(child_lines, mode))
    return st


