C_LIKE_LANGS = {
    "C", "C Header", "C++", "C++ Header", "C++ Module", "C#", "Java", "JavaScript", "TypeScript", "JSX", "TSX",
    "Go", "Rust", "D", "D2", "Dart", "Kotlin", "Swift", "Scala", "Groovy", "PHP", "Objective-C", "Objective-C++",
