SQL_LANGS = {"SQL", "PLSQL", "PRQL"}
XML_LIKE_LANGS = {"XML", "XSL", "SVG", "XAML", "Vue", "Svelte", "Astro", "AXAML"}


def count_lines_for_language(lines: List[str], lang: str) -> Stats:
    if lang == "Jupyter Notebooks":
        # Observed tokei 14 records ipynb files but reports zero textual lines.
        return Stats()
    if lang in {"Markdown", "MDX", "Unreal Markdown"}:
        return count_markdown(lines)
    if lang in {"HTML", "Vue", "Svelte", "Astro"}:
        return count_html(lines)
    if lang == "Python":
        return count_python(lines)
    if lang == "Batch":
        return count_batch(lines)
    if lang in NO_COMMENT_LANGS:
        return count_no_comments(lines)
    if lang in PLAIN_COMMENT_LANGS:
        return count_plain_text(lines)
    if lang in HASH_LANGS:
        return count_first_marker(lines, ["#"])
    if lang in SEMICOLON_LANGS:
        return count_first_marker(lines, [";"])
    if lang in PERCENT_LANGS:
        return count_first_marker(lines, ["%"])
    if lang in SQL_LANGS:
        return count_generic(lines, ["--"], [("/*", "*/", False)])
    if lang == "Lua":
        return count_generic(lines, ["--"], [("--[[", "]]", False)])
    if lang == "Haskell":
        return count_generic(lines, ["--"], [("{-", "-}", True)])
    if lang in CSS_LIKE_LANGS:
        return count_generic(lines, [], [("/*", "*/", False)])
    if lang in XML_LIKE_LANGS:
        return count_generic(lines, [], [("<!--", "-->", False)], quote_chars='"\'')
    if lang in C_LIKE_LANGS:
        nested = lang in {"Rust", "Swift"}
        if lang == "PHP":
            return count_generic(lines, ["//", "#"], [("/*", "*/", False)])
        return count_generic(lines, ["//"], [("/*", "*/", nested)])
    # Sensible default for programming languages: nonblank lines are code.
    return count_no_comments(lines)


def count_file(abs_path: str, display_path: str, lang: str) -> Report:
    text = read_file_text(abs_path)
    lines = split_lines(text)
    stats = count_lines_for_language(lines, lang)
    return Report(display_path, stats)


# ---------------------------------------------------------------------------
# Ignore/exclude handling and filesystem traversal


@dataclass
class IgnorePattern:
    base_abs: str
    pattern: str


def _load_ignore_file(path: str) -> List[str]:
    pats: List[str] = []
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            for raw in f:
                line = raw.rstrip("\n")
                if not line or line.lstrip().startswith("#"):
                    continue
                pats.append(line)
    except OSError:
        pass
    return pats


def _is_vcs_active(root_abs: str) -> bool:
    cur = os.path.abspath(root_abs)
    while True:
        if os.path.isdir(os.path.join(cur, ".git")):
            return True
        parent = os.path.dirname(cur)
        if parent == cur:
            return False
        cur = parent


def _match_one_pattern(pattern: str, rel: str, basename: str, is_dir: bool) -> bool:
    pat = pattern.strip()
    if not pat or pat.startswith("!"):
        return False
    # Escaped leading hash/exclamation are treated literally in a lightweight way.
    if pat.startswith("\\") and len(pat) > 1:
        pat = pat[1:]
    dir_only = pat.endswith("/")
    if dir_only:
        pat = pat.rstrip("/")
    pat = pat.lstrip("/")
    rel = rel.replace(os.sep, "/")
    basename = basename.replace(os.sep, "/")
    if dir_only and not is_dir:
        # A directory-only pattern also excludes files underneath that directory.
        pass
    if "/" not in pat:
        if fnmatch.fnmatchcase(basename, pat):
            return True
        if dir_only and (rel == pat or rel.startswith(pat + "/")):
            return True
        return False
    if fnmatch.fnmatchcase(rel, pat):
        return True
    if dir_only and (rel == pat or rel.startswith(pat + "/")):
        return True
    return False


def _is_ignored(abs_path: str, is_dir: bool, patterns: List[IgnorePattern]) -> bool:
    basename = os.path.basename(abs_path)
    for ip in patterns:
        try:
            rel = os.path.relpath(abs_path, ip.base_abs)
        except ValueError:
            continue
        if rel.startswith(".."):
            continue
        if _match_one_pattern(ip.pattern, rel, basename, is_dir):
            return True
    return False


def _matches_exclude(display_path: str, abs_path: str, is_dir: bool, excludes: List[str]) -> bool:
    if not excludes:
        return False
    basename = os.path.basename(display_path.rstrip(os.sep))
    rel_cwd = os.path.relpath(abs_path, os.getcwd()).replace(os.sep, "/")
    disp = display_path.replace(os.sep, "/")
    for pat in excludes:
        p = pat.strip()
        if not p or p.startswith("!"):
            continue
        dir_only = p.endswith("/")
        p2 = p.rstrip("/").lstrip("/")
        if "/" not in p2:
            if fnmatch.fnmatchcase(basename, p2):
                return True
            if dir_only and (basename == p2):
                return True
        else:
            if fnmatch.fnmatchcase(rel_cwd, p2) or fnmatch.fnmatchcase(disp, p2):
                return True
            if dir_only and (rel_cwd == p2 or rel_cwd.startswith(p2 + "/")):
                return True
    return False


def _is_hidden_name(name: str) -> bool:
    return name.startswith(".") and name not in {".", ".."}


def gather_files(inputs: List[str], cfg: Config) -> List[Tuple[str, str]]:
    files: List[Tuple[str, str]] = []  # (abs_path, display_path)

    def walk(abs_dir: str, disp_dir: str, root_abs: str, patterns: List[IgnorePattern], vcs_active: bool) -> None:
        local_patterns = list(patterns)
        if not cfg.no_ignore and not cfg.no_ignore_dot:
            for fname in (".ignore", ".tokeignore"):
                for pat in _load_ignore_file(os.path.join(abs_dir, fname)):
                    local_patterns.append(IgnorePattern(abs_dir, pat))
        if not cfg.no_ignore and not cfg.no_ignore_vcs and vcs_active:
            for pat in _load_ignore_file(os.path.join(abs_dir, ".gitignore")):
                local_patterns.append(IgnorePattern(abs_dir, pat))
        try:
            entries = sorted(os.listdir(abs_dir))
        except OSError:
            return
        dirs: List[str] = []
        regulars: List[str] = []
        for name in entries:
            abs_path = os.path.join(abs_dir, name)
            disp_path = os.path.join(disp_dir, name)
            try:
                is_dir = os.path.isdir(abs_path)
            except OSError:
                continue
            if not cfg.hidden and _is_hidden_name(name):
                continue
            if _matches_exclude(disp_path, abs_path, is_dir, cfg.excludes):
                continue
            if _is_ignored(abs_path, is_dir, local_patterns):
                continue
            if is_dir:
                dirs.append(name)
            elif os.path.isfile(abs_path):
                regulars.append(name)
        for name in regulars:
            files.append((os.path.join(abs_dir, name), os.path.join(disp_dir, name)))
        for name in dirs:
            walk(os.path.join(abs_dir, name), os.path.join(disp_dir, name), root_abs, local_patterns, vcs_active)

    for inp in inputs:
        abs_inp = os.path.abspath(inp)
        if os.path.isfile(abs_inp):
            files.append((abs_inp, inp))
        elif os.path.isdir(abs_inp):
            vcs_active = False if cfg.no_ignore or cfg.no_ignore_vcs else _is_vcs_active(abs_inp)
            walk(abs_inp, inp, abs_inp, [], vcs_active)
    return files


# ---------------------------------------------------------------------------
# Aggregation and serialization


def warn_unknown(ext: str) -> None:
    now = _dt.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
    print(f"[{now} WARN  tokei::language::language_type] Unknown extension: {ext}", file=sys.stderr)


def build_aggregates(cfg: Config) -> Dict[str, LangAgg]:
    inputs = cfg.inputs or ["."]
    aggregates: Dict[str, LangAgg] = {}
    type_filter = {t.strip().lower() for t in cfg.types or [] if t.strip()}

    for abs_path, disp_path in gather_files(inputs, cfg):
        first_text = None
        try:
            with open(abs_path, "rb") as f:
                first_text = f.read(512).decode("utf-8", errors="replace")
        except OSError:
            first_text = ""
        lang, unknown_ext = detect_language(disp_path, abs_path, first_text)
        if lang is None:
            if cfg.verbose >= 1 and unknown_ext:
                warn_unknown(unknown_ext)
            continue
        if type_filter and lang.lower() not in type_filter:
            continue
        report = count_file(abs_path, disp_path, lang)
        agg = aggregates.setdefault(lang, LangAgg(lang))
        agg.blanks += report.stats.blanks
        agg.code += report.stats.code
        agg.comments += report.stats.comments
        agg.reports.append(report)
        for child_lang in sorted(report.stats.blobs):
            child_stats = report.stats.blobs[child_lang]
            agg.children[child_lang].append(Report(report.name, child_stats))

    for agg in aggregates.values():
        agg.reports.sort(key=lambda r: r.name)
        for reports in agg.children.values():
            reports.sort(key=lambda r: r.name)
    return aggregates


def stats_json(stats: Stats, streaming: bool = False) -> OrderedDict:
    if streaming:
        od = OrderedDict()
        od["blanks"] = stats.blanks
        od["blobs"] = blobs_json(stats.blobs, streaming=True)
        od["code"] = stats.code
        od["comments"] = stats.comments
        return od
    od = OrderedDict()
    od["blanks"] = stats.blanks
    od["code"] = stats.code
    od["comments"] = stats.comments
    od["blobs"] = blobs_json(stats.blobs, streaming=False)
    return od


def blobs_json(blobs: Dict[str, Stats], streaming: bool = False) -> OrderedDict:
    od = OrderedDict()
    for lang in sorted(blobs):
        od[lang] = stats_json(blobs[lang], streaming=streaming)
    return od


def report_json(report: Report, streaming: bool = False) -> OrderedDict:
    od = OrderedDict()
    if streaming:
        od["name"] = report.name
        od["stats"] = stats_json(report.stats, streaming=True)
    else:
        od["stats"] = stats_json(report.stats, streaming=False)
        od["name"] = report.name
    return od


def aggregate_json(aggregates: Dict[str, LangAgg]) -> OrderedDict:
    root = OrderedDict()
    total = Stats()
    total_children = OrderedDict()
    for lang in sorted(aggregates):
        agg = aggregates[lang]
        lang_obj = OrderedDict()
        lang_obj["blanks"] = agg.blanks
        lang_obj["code"] = agg.code
        lang_obj["comments"] = agg.comments
        lang_obj["reports"] = [report_json(r) for r in agg.reports]
        children_od = OrderedDict()
        for child_lang in sorted(agg.children):
            children_od[child_lang] = [report_json(r) for r in agg.children[child_lang]]
        lang_obj["children"] = children_od
        lang_obj["inaccurate"] = False
        root[lang] = lang_obj

        total.add_own(agg.total_stats())
        total_children[lang] = [report_json(r) for r in agg.reports]
    total_obj = OrderedDict()
    total_obj["blanks"] = total.blanks
    total_obj["code"] = total.code
    total_obj["comments"] = total.comments
    total_obj["reports"] = []
    total_obj["children"] = total_children
    total_obj["inaccurate"] = False
    root["Total"] = total_obj
    return root


# ---------------------------------------------------------------------------
# Human-readable and streaming output


def _format_num(n: int, style: str) -> str:
    if style == "commas":
        return f"{n:,}"
    if style == "dots":
        return f"{n:,}".replace(",", ".")
    if style == "underscores":
        return f"{n:_}"
    return str(n)


def _metric(agg: LangAgg, key: str) -> int:
    if key == "files":
        return agg.files
    if key == "lines":
        return agg.own_lines
    if key == "blanks":
        return agg.blanks
    if key == "code":
        return agg.code
    if key == "comments":
        return agg.comments
    return 0


def _sorted_langs(aggregates: Dict[str, LangAgg], cfg: Config, include_zero: bool = False) -> List[str]:
    langs = [l for l, a in aggregates.items() if include_zero or a.total_stats().lines > 0]
    sort_key = cfg.sort or cfg.rsort
    reverse_sort = cfg.rsort is not None
    if sort_key is None:
        langs.sort(key=lambda l: l.lower())
        return langs
    if reverse_sort:
        # Ascending metric; ties are reverse-alphabetical as observed.
        langs.sort(key=lambda l: ( _metric(aggregates[l], sort_key), "".join(chr(0x10FFFF - ord(c)) for c in l.lower()) ))
    else:
        langs.sort(key=lambda l: (-_metric(aggregates[l], sort_key), l.lower()))
    return langs


def _ordered_for_table(aggregates: Dict[str, LangAgg], cfg: Config) -> List[str]:
    langs = _sorted_langs(aggregates, cfg, include_zero=False)
    if cfg.compact:
        return langs
    simple = [l for l in langs if not aggregates[l].children]
    complex_ = [l for l in langs if aggregates[l].children]
    return simple + complex_


def _row_widths(columns: Optional[int]) -> Tuple[int, int, int]:
    border = 81
    if columns is not None and columns > 81:
        border = columns
    name_w = max(15, border - 66)
    row_len = border - 1
    return border, row_len, name_w


def _fit_left(text: str, width: int) -> str:
    if len(text) <= width:
        return text.ljust(width)
    if width <= 1:
        return text[-width:]
    return "|" + text[-(width - 1):]


def _format_row(name: str, files: Optional[int], stats: Stats, name_w: int, num_style: str) -> str:
    file_s = "" if files is None else _format_num(files, num_style)
    return (
        f" {_fit_left(name, name_w)}"
        f"{file_s:>12}"
        f"{_format_num(stats.lines, num_style):>13}"
        f"{_format_num(stats.code, num_style):>13}"
        f"{_format_num(stats.comments, num_style):>13}"
        f"{_format_num(stats.blanks, num_style):>13}"
