def _format_file_row(label: str, stats: Stats, name_w: int, num_style: str) -> str:
    field_w = name_w + 12
    return (
        f" {_fit_left(label, field_w)}"
        f"{_format_num(stats.lines, num_style):>13}"
        f"{_format_num(stats.code, num_style):>13}"
        f"{_format_num(stats.comments, num_style):>13}"
        f"{_format_num(stats.blanks, num_style):>13}"
    )


def total_for_aggregates(aggregates: Dict[str, LangAgg]) -> Tuple[int, Stats]:
    files = 0
    stats = Stats()
    for agg in aggregates.values():
        files += agg.files
        stats.add_own(agg.total_stats())
