# CLI parsing/errors


def cli_error(message: str, usage: Optional[str] = None) -> int:
    print(f"error: {message}", file=sys.stderr)
    if usage:
        print("", file=sys.stderr)
        print(usage, file=sys.stderr)
    print("", file=sys.stderr)
    print("For more information, try '--help'.", file=sys.stderr)
    return 2


def missing_value(opt: str) -> int:
    return cli_error(f"a value is required for '{opt}' but none was supplied")


def parse_int_value(value: str, opt: str) -> Tuple[Optional[int], Optional[int]]:
    try:
        return int(value), None
    except ValueError:
        return None, cli_error(f"invalid value '{value}' for '{opt}': invalid digit found in string")


def parse_args(argv: List[str]) -> Tuple[Optional[Config], int]:
    cfg = Config()
    i = 0
    positional_mode = False
    while i < len(argv):
        arg = argv[i]
        if positional_mode:
            cfg.inputs.append(arg)
            i += 1
            continue
        if arg == "--":
            positional_mode = True
            i += 1
            continue
        if arg in ("-h", "--help"):
            sys.stdout.write(HELP_TEXT or "")
            return None, 0
        if arg in ("-V", "--version"):
            print(VERSION)
            return None, 0
        if arg == "-f" or arg == "--files":
            cfg.files = True
        elif arg == "--hidden":
            cfg.hidden = True
        elif arg == "-l" or arg == "--languages":
            cfg.languages = True
        elif arg == "--no-ignore":
            cfg.no_ignore = True
            cfg.no_ignore_dot = True
            cfg.no_ignore_parent = True
            cfg.no_ignore_vcs = True
        elif arg == "--no-ignore-dot":
            cfg.no_ignore_dot = True
