def run(argv: List[str]) -> int:
    cfg, rc = parse_args(argv)
    if cfg is None:
        return rc

    if cfg.languages:
        sys.stdout.write(LANGUAGES_TEXT)
        return 0

    if cfg.input_file:
        if cfg.input_file == "stdin":
            try:
                _ = sys.stdin.read()
            except Exception:
                pass
        elif not os.path.exists(cfg.input_file):
            return input_file_error(cfg.input_file)
        else:
            # The observed binary accepts existing input files in this build but
            # does not visibly merge them with the current run for the JSON it
            # emits.  Reading is unnecessary for the observable result.
            pass

    inputs = cfg.inputs or ["."]
    for inp in inputs:
        if not os.path.exists(inp):
            print(f"Error: '{inp}' not found.", file=sys.stderr)
            print("", file=sys.stderr)
            return 1

    cfg.inputs = inputs
    aggregates = build_aggregates(cfg)

    if cfg.streaming:
        print_streaming(aggregates, cfg.streaming)
    elif cfg.output == "json":
        sys.stdout.write(json.dumps(aggregate_json(aggregates), separators=(",", ":"), ensure_ascii=False))
    else:
        print_table(aggregates, cfg)
    return 0


def main() -> None:
    sys.exit(run(sys.argv[1:]))


if __name__ == "__main__":
    main()
