def print_table(aggregates: Dict[str, LangAgg], cfg: Config) -> None:
    border, _row_len, name_w = _row_widths(cfg.columns)
    heavy = "━" * border
    light = "─" * border
    print(heavy)
    print(f" {'Language':<{name_w}}{'Files':>12}{'Lines':>13}{'Code':>13}{'Comments':>13}{'Blanks':>13}")
    print(heavy)

    ordered = _ordered_for_table(aggregates, cfg)
    printed_any = False
    simple_count = len([l for l in ordered if not aggregates[l].children]) if not cfg.compact else len(ordered)

    if cfg.files:
        for idx, lang in enumerate(ordered):
            agg = aggregates[lang]
            if agg.total_stats().lines == 0:
                continue
            if printed_any:
                print(light)
            print(_format_row(lang, agg.files, agg.own_stats, name_w, cfg.num_format))
            if agg.children and not cfg.compact:
                for child_lang in sorted(agg.children):
                    child_total = Stats()
                    for rep in agg.children[child_lang]:
                        child_total.add_own(rep.stats.total_with_blobs())
                    print(_format_row(f"|- {child_lang}", len(agg.children[child_lang]), child_total, name_w, cfg.num_format))
                print(_format_row("(Total)", None, agg.total_stats(), name_w, cfg.num_format))
            print(light)
            for rep in agg.reports:
                if rep.stats.total_with_blobs().lines == 0:
                    continue
                if agg.children and not cfg.compact:
                    print(f" {rep.name}")
                    print(_format_file_row(f"|- {lang}", rep.stats.copy_without_blobs(), name_w, cfg.num_format))
                    for child_lang in sorted(rep.stats.blobs):
                        print(_format_file_row(f"|- {child_lang}", rep.stats.blobs[child_lang], name_w, cfg.num_format))
                    print(_format_file_row(rep.name, rep.stats.copy_without_blobs(), name_w, cfg.num_format))
                else:
                    print(_format_file_row(rep.name, rep.stats.copy_without_blobs(), name_w, cfg.num_format))
            printed_any = True
    else:
        for idx, lang in enumerate(ordered):
            agg = aggregates[lang]
            if agg.total_stats().lines == 0:
                continue
            if not cfg.compact and agg.children and not printed_any:
                # first visible row can be a complex language; no separator then
                pass
            elif not cfg.compact and agg.children and idx == simple_count and simple_count > 0:
                print(light)
            elif not cfg.compact and agg.children and printed_any:
                # Separators between complex sections.
                prev_langs = [l for l in ordered[:idx] if aggregates[l].total_stats().lines > 0]
                if prev_langs and aggregates[prev_langs[-1]].children:
                    print(light)
            print(_format_row(lang, agg.files, agg.own_stats, name_w, cfg.num_format))
            if agg.children and not cfg.compact:
                for child_lang in sorted(agg.children):
                    child_total = Stats()
                    for rep in agg.children[child_lang]:
                        child_total.add_own(rep.stats.total_with_blobs())
                    print(_format_row(f"|- {child_lang}", len(agg.children[child_lang]), child_total, name_w, cfg.num_format))
                print(_format_row("(Total)", None, agg.total_stats(), name_w, cfg.num_format))
            printed_any = True

    total_files, total_stats = total_for_aggregates(aggregates)
    print(heavy)
    print(_format_row("Total", total_files, total_stats, name_w, cfg.num_format))
    print(heavy)


def print_streaming(aggregates: Dict[str, LangAgg], fmt: str) -> None:
    langs = sorted(aggregates)
    if fmt == "simple":
        print(f"{'# language':>10} {'path':<80} {'lines':>12} {'code':>12} {'comments':>12} {'blanks':>12}")
        print(f"{'#' * 10} {'#' * 80} {'#' * 12} {'#' * 12} {'#' * 12} {'#' * 12}")
        for lang in langs:
            for rep in sorted(aggregates[lang].reports, key=lambda r: r.name):
                st = rep.stats.copy_without_blobs()
                print(f"{lang:>10} {rep.name:<80} {st.lines:>12} {st.code:>12} {st.comments:>12} {st.blanks:>12}")
    else:
        for lang in langs:
            for rep in sorted(aggregates[lang].reports, key=lambda r: r.name):
                od = OrderedDict()
                od["language"] = lang
                od["stats"] = report_json(rep, streaming=True)
                print(json.dumps(od, separators=(",", ":"), ensure_ascii=False))


